### Example: Medicaid Member Dashboard Date Display

A member's authorization expiry date must display correctly regardless of locale:

```typescript
import { formatDate } from '@mmes/core/locale';
import { useLocale } from '@portal/i18n';  // Portal Studio locale context

function AuthorizationCard({ authExpiry }: { authExpiry: string }) {
  const locale = useLocale();  // 'en-US' or 'es-MX' from portal config
  return (
    <div>
      <span>Authorization expires: {formatDate(authExpiry, locale, 'long')}</span>
    </div>
  );
}
// en-US: "Authorization expires: August 1, 2026"
// es-MX: "Authorization expires: 1 de agosto de 2026"
```
